import { expect, it } from 'vitest';
import { createPointCompiler } from '/Users/yazhou/code/nexus-service/packages/plugin-runtime/src/ui/point-compiler.ts';
import { CONSOLE_EXTENSION_POINTS, CONSOLE_EXTENSION_POINT_CATALOG, CONSOLE_PROFILES, PLUGIN_REF_CONTRACT } from '/Users/yazhou/code/nexus-service/packages/console-core-api/src/index.ts';
import { CLUSTER_EXTENSION_POINTS, CLUSTER_EXTENSION_POINT_CATALOG, RESOURCE_REF_CONTRACT } from '/Users/yazhou/code/nexus-service/packages/cluster-api/src/index.ts';

const sources = [
  { owner: 'console-core', points: CONSOLE_EXTENSION_POINTS, annotations: CONSOLE_EXTENSION_POINT_CATALOG },
  { owner: 'cluster', points: CLUSTER_EXTENSION_POINTS, annotations: CLUSTER_EXTENSION_POINT_CATALOG },
];
const contracts = { profiles: CONSOLE_PROFILES, refContracts: [PLUGIN_REF_CONTRACT, RESOURCE_REF_CONTRACT] };
const compile = createPointCompiler(contracts);
const variant = process.env.CONTRACT_ABLATION;
function candidate(sources: any[]) {
  let input: any = variant === 'no-envelope' ? sources : { plugins: sources };
  if (variant !== 'no-json') input = JSON.parse(JSON.stringify(input));
  const items = variant === 'no-envelope' ? input : input.plugins;
  return items.flatMap((source: any) => {
    const annotations = source.annotations.map((a: any) => variant === 'no-catalog-kind'
      ? { ref: a.ref, title: a.title, description: a.description } : a);
    return source.points.map((point: any) => {
      const note = annotations.find((a: any) => a.ref.ownerPluginId === source.owner && a.ref.id === point.id && a.ref.contractMajor === point.contractMajor);
      if (!note) throw Error('ANNOTATION_MISSING');
      if (note.kind !== undefined && note.kind !== point.kind) throw Error('CATALOG_KIND_MISMATCH');
      const resolved = variant === 'no-compiler' ? point : compile(point);
      return { owner: source.owner, ...resolved, title: note.title, description: note.description };
    });
  }).sort((a: any,b: any) => `${a.owner}/${a.id}`.localeCompare(`${b.owner}/${b.id}`));
}
const expected = sources.flatMap(s => s.points.map(p => {
  const note = s.annotations.find(a => a.ref.id === p.id)!;
  return { owner: s.owner, ...compile(p), title: note.title, description: note.description };
})).sort((a,b) => `${a.owner}/${a.id}`.localeCompare(`${b.owner}/${b.id}`));
it('retains all 9 owned Point identities and kinds', () => {
  const identity = (p: any) => [p.owner,p.id,p.contractMajor,p.kind];
  expect(candidate(sources).map(identity)).toEqual(expected.map(identity));
  expect(candidate(sources)).toHaveLength(9);
});
it('retains complete compiled projection and annotations', () => {
  expect(candidate(sources)).toEqual(expected);
});
it('exposes concrete ResourceRef schema rather than parameter template', () => {
  const point = candidate(sources).find((p: any) => p.owner === 'cluster' && p.id === 'node.actions');
  expect(point.contextSchema.properties.itemRef).toEqual(RESOURCE_REF_CONTRACT.schema);
  expect(point.allowedPolicyDimensions).toContain('capability');
});
it('rejects a Point whose declared Ref binding is unavailable', () => {
  const changed = structuredClone(sources) as any;
  changed[1].points.find((p: any) => p.id === 'node.actions').bindings.itemRefContract = 'cluster.missing-ref@1';
  expect(() => candidate(changed)).toThrow('REF_CONTRACT_MISSING');
});
it('is deterministic and leaves source data unchanged', () => {
  const before = JSON.stringify(sources);
  expect(candidate(sources)).toEqual(candidate(sources));
  expect(JSON.stringify(sources)).toBe(before);
});
